import org.jfree.chart.util.SerialUtilities;
import org.jfree.data.category.CategoryDataset;
import org.jfree.data.statistics.StatisticalCategoryDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StatisticalBarRenderer_drawVerticalItem_TriageGen2Test {

    private StatisticalBarRenderer renderer;

    @Mock
    private Graphics2D g2;
    @Mock
    private CategoryItemRendererState state;
    @Mock
    private Rectangle2D dataArea;
    @Mock
    private CategoryPlot plot;
    @Mock
    private CategoryAxis domainAxis;
    @Mock
    private ValueAxis rangeAxis;
    @Mock
    private StatisticalCategoryDataset dataset;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // We use a subclass to expose the protected method for testing
        renderer = new StatisticalBarRenderer() {
            @Override
            public void drawVerticalItem(Graphics2D g2, CategoryItemRendererState state, Rectangle2D dataArea, 
                                         CategoryPlot plot, CategoryAxis domainAxis, ValueAxis rangeAxis, 
                                         StatisticalCategoryDataset dataset, int row, int column) {
                super.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, row, column);
            }

            // Overriding helper methods to control behavior and avoid complex setup
            @Override
            protected int getColumnCount() { return 5; }
            @Override
            protected int getRowCount() { return 2; }
            @Override
            protected double getItemMargin() { return 0.1; }
            @Override
            protected double getLowerClip() { return -10.0; }
            @Override
            protected double getUpperClip() { return 10.0; }
            @Override
            protected boolean isDrawBarOutline() { return true; }
            @Override
            protected Paint getItemPaint(int row, int col) { return Color.BLUE; }
            @Override
            protected Stroke getItemStroke(int row, int col) { return null; }
            @Override
            protected Paint getItemOutlinePaint(int row, int col) { return Color.BLACK; }
            @Override
            protected Stroke getItemOutlineStroke(int row, int col) { return null; }
            @Override
            protected org.jfree.chart.labels.CategoryItemLabelGenerator getItemLabelGenerator(int row, int col) { return null; }
            @Override
            protected boolean isItemLabelVisible(int row, int col) { return false; }
            @Override
            protected void drawItemLabel(Graphics2D g2, StatisticalCategoryDataset dataset, int row, int col, 
                                         org.jfree.chart.labels.CategoryItemLabelGenerator generator, 
                                         Rectangle2D bar, boolean isNegative) {}
            @Override
            protected void addItemEntity(org.jfree.chart.entity.EntityCollection entities, StatisticalCategoryDataset dataset, 
                                         int row, int col, Rectangle2D bar) {}
        };

        // Default Mock behaviors
        when(plot.getDomainAxisEdge()).thenReturn(RectangleEdge.BOTTOM);
        when(plot.getRangeAxisEdge()).thenReturn(RectangleEdge.LEFT);
        when(dataArea.getWidth()).thenReturn(100.0);
        when(domainAxis.getCategoryStart(anyInt(), anyInt(), any(), any())).thenReturn(10.0);
        when(state.getBarWidth()).thenReturn(5.0);
        when(dataset.getMeanValue(anyInt(), anyInt())).thenReturn(5.0);
        when(dataset.getStdDevValue(anyInt(), anyInt())).thenReturn(1.0);
        when(rangeAxis.valueToJava2D(anyDouble(), any(), any())).thenAnswer(inv -> (Double)inv.getArgument(0));
    }

    @Test
    public void testDrawVerticalItem_Case9_PositiveValue() {
        // Case 9: uclip > 0, lclip > 0, value > lclip
        // Default setup: uclip=10, lclip=-10 is actually case 9/10/11/12 logic in code
        // Wait, the code logic: if (uclip <= 0) ... else if (lclip <= 0) ... else { ... }
        // With uclip=10 and lclip=-10, it goes to the 'else' block (Cases 9, 10, 11, 12)

        renderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
        verify(g2, atLeastOnce()).draw(any(Line2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case1_ValueTooHigh() {
        // Case 1: uclip <= 0 and value >= uclip
        // To trigger uclip <= 0, we need to override the renderer's clip
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getUpperClip() { return -5.0; }
            @Override protected double getLowerClip() { return -10.0; }
            @Override protected int getColumnCount() { return 1; }
            @Override protected int getRowCount() { return 1; }
            @Override protected double getItemMargin() { return 0.1; }
            @Override protected double getBarWidth() { return 5.0; } // dummy
            @Override protected int getRowCount() { return 1; }
            @Override protected int getColumnCount() { return 1; }
            @Override protected double getItemMargin() { return 0.1; }
            @Override protected double getLowerClip() { return -10.0; }
            @Override protected double getUpperClip() { return -5.0; }
            @Override protected boolean isDrawBarOutline() { return false; }
            @Override protected Paint getItemPaint(int r, int c) { return Color.RED; }
            @Override protected Stroke getItemStroke(int r, int c) { return null; }
            @Override protected Paint getItemOutlinePaint(int r, int c) { return Color.BLACK; }
            @Override protected Stroke getItemOutlineStroke(int r, int c) { return null; }
            @Override protected org.jfree.chart.labels.CategoryItemLabelGenerator getItemLabelGenerator(int r, int c) { return null; }
            @Override protected boolean isItemLabelVisible(int r, int c) { return false; }
            @Override protected void drawItemLabel(Graphics2D g2, StatisticalCategoryDataset d, int r, int c, org.jfree.chart.labels.CategoryItemLabelGenerator gen, Rectangle2D b, boolean neg) {}
            @Override protected void addItemEntity(org.jfree.chart.entity.EntityCollection e, StatisticalCategoryDataset d, int r, int c, Rectangle2D b) {}
            @Override protected double getBarWidth() { return 5.0; }
            @Override protected double getItemMargin() { return 0.1; }
            @Override protected int getColumnCount() { return 1; }
            @Override protected int getRowCount() { return 1; }
        };

        // Since the method is protected, we use the one from the setup which is a subclass
        // Let's redefine the test to use a more flexible approach
    }

    // Because the method is protected and relies heavily on internal state, 
    // we use a specialized test subclass to hit all branches.

    private static class TestableRenderer extends StatisticalBarRenderer {
        double lclip = -10, uclip = 10, margin = 0.1, barWidth = 5.0;
        int rows = 1, cols = 1;
        boolean drawOutline = false;
        org.jfree.chart.labels.CategoryItemLabelGenerator labelGen = null;
        boolean labelVisible = false;
        org.jfree.chart.entity.EntityCollection entities = null;
        Stroke errorStroke = null;
        Paint errorPaint = null;

        @Override protected double getLowerClip() { return lclip; }
        @Override protected double getUpperClip() { return uclip; }
        @Override protected double getItemMargin() { return margin; }
        @Override protected int getRowCount() { return rows; }
        @Override protected int getColumnCount() { return cols; }
        @Override protected boolean isDrawBarOutline() { return drawOutline; }
        @Override protected Paint getItemPaint(int r, int c) { return Color.BLUE; }
        @Override protected Stroke getItemStroke(int r, int c) { return null; }
        @Override protected Paint getItemOutlinePaint(int r, int c) { return Color.BLACK; }
        @Override protected Stroke getItemOutlineStroke(int r, int c) { return null; }
        @Override protected org.jfree.chart.labels.CategoryItemLabelGenerator getItemLabelGenerator(int r, int c) { return labelGen; }
        @Override protected boolean isItemLabelVisible(int r, int c) { return labelVisible; }
        @Override protected void drawItemLabel(Graphics2D g2, StatisticalCategoryDataset d, int r, int c, org.jfree.chart.labels.CategoryItemLabelGenerator gen, Rectangle2D b, boolean neg) {}
        @Override protected void addItemEntity(org.jfree.chart.entity.EntityCollection e, StatisticalCategoryDataset d, int r, int c, Rectangle2D b) { super.addItemEntity(e, d, r, c, b); }
        @Override protected double getBarWidth() { return barWidth; } 
        // Note: the original code calls state.getBarWidth(), not this.getBarWidth(). 
        // I will fix that in the test logic.

        @Override public Stroke getErrorIndicatorStroke() { return errorStroke; }
        @Override public Paint getErrorIndicatorPaint() { return errorPaint; }
    }

    @Test
    public void testAllBranches() throws Exception {
        TestableRenderer tr = new TestableRenderer();

        // 1. Case: uclip <= 0, value >= uclip (Return)
        tr.uclip = -5.0; tr.lclip = -10.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(0.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, never()).fill(any());

        // 2. Case: uclip <= 0, value < uclip (but value <= lclip)
        tr.uclip = -5.0; tr.lclip = -10.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(-15.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any());

        // 3. Case: lclip <= 0, value >= uclip (Cap at uclip)
        tr.uclip = 10.0; tr.lclip = -5.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(20.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any());

        // 4. Case: lclip <= 0, value <= lclip (Cap at lclip)
        tr.uclip = 10.0; tr.lclip = -5.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(-20.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any());

        // 5. Case: lclip > 0, value <= lclip (Return)
        tr.uclip = 10.0; tr.lclip = 5.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(2.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, never()).fill(any());

        // 6. Case: lclip > 0, value >= uclip (Cap at uclip)
        tr.uclip = 10.0; tr.lclip = 5.0;
        when(dataset.getMeanValue(0, 0)).thenReturn(15.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any());

        // 7. Test Series Gap logic (seriesCount > 1)
        tr.rows = 2; tr.cols = 2; tr.margin = 0.1;
        when(state.getBarWidth()).thenReturn(5.0);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 1, 0);
        verify(g2, atLeastOnce()).fill(any());

        // 8. Test Outline logic
        tr.drawOutline = true;
        when(state.getBarWidth()).thenReturn(5.0); // > 3
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).draw(any(Rectangle2D.class));

        // 9. Test Error Indicator Stroke/Paint
        tr.errorStroke = Color.RED; // Use color as a proxy for stroke in mock if needed, but here we use real objects
        tr.errorStroke = null; // testing the 'else' part
        tr.errorPaint = Color.GREEN; 
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).setPaint(Color.GREEN);

        // 10. Test Label Generator
        tr.labelGen = mock(org.jfree.chart.labels.CategoryItemLabelGenerator.class);
        tr.labelVisible = true;
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        // verified via no exception and execution flow

        // 11. Test Entity Collection
        org.jfree.chart.entity.EntityCollection ec = mock(org.jfree.chart.entity.EntityCollection.class);
        when(state.getEntityCollection()).thenReturn(ec);
        tr.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        // verify interaction via side effect if needed, but here we just ensure it doesn't crash
    }
}

// Placeholder for RectangleEdge if not available in environment
enum RectangleEdge { TOP, BOTTOM, LEFT, RIGHT }
